import httpx

def download_large_file(url: str, output_path: str, chunk_size: int = 8192):
    """Download a large file and stream it to disk in chunks."""
    with httpx.stream("GET", url) as response:
        response.raise_for_status()
        with open(output_path, "wb") as f:
            for chunk in response.iter_bytes(chunk_size=chunk_size):
                if chunk:
                    f.write(chunk)

if __name__ == "__main__":
    download_large_file("https://example.com/big.bin", "big.bin")
